// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.cognitive.modelimport com.roshan.persona.common.CorrelationIdimport java.time.Instant/** * NOUS — Cognitive Data Models (Module 7 v2 — Step 7.1). * * All data types used by the Cognitive Layer. Pure data classes — no logic, * no Android dependencies. Fully testable. * * ## Model groups * *  1. **Reasoning** — ReasoningTrace, ReasoningStep, VerificationResult. *  2. **Planning** — TaskPlan, SubTask, DependencyGraph, ResourceEstimate. *  3. **Clarification** — ClarificationQuestion. *  4. **Decision** — DecisionResult, DecisionOption, DecisionCriterion. *  5. **Problem Solving** — ProblemSolution, Constraint, SolutionApproach. *  6. **Replanning** — ReplanResult, PlanExecutionResult, PlanStatus, ExecutionStatus. *  7. **Storage** — StoredReasoningTrace, UserFeedback. *  8. **Uncertainty** — UncertaintyAction. * * @see <a href="docs/strategy/module-7-cognitive-strategy-v2.md">§Architecture</a> */// ═══════════════════════════════════════════════════════════════════════════// 1. REASONING MODELS// ═══════════════════════════════════════════════════════════════════════════/** * A complete reasoning trace — the user-visible chain-of-thought. * * Distinct from Brain's `WorkflowTrace` (developer-facing audit log). * This is what the user sees when they long-press → "Show reasoning". * * @param steps the reasoning steps (thought → action → observation). * @param finalAnswer the answer NOUS gives the user. * @param confidence 0.0–1.0 — used by [com.roshan.persona.cognitive.engine.ConfidenceModulator]. * @param alternativesConsidered discarded paths ("I initially thought X..."). * @param correctionApplied true if self-correction changed the answer (Q2: show both). * @param originalAnswer the pre-correction answer (null if no correction). * @param timeMs total reasoning time. */data class ReasoningTrace(    val steps: List<ReasoningStep>,    val finalAnswer: String,    val confidence: Float,    val alternativesConsidered: List<String> = emptyList(),    val correctionApplied: Boolean = false,    val originalAnswer: String? = null,    val timeMs: Long = 0,    val correlationId: CorrelationId = CorrelationId.generate(),) {    init {        require(confidence in 0f..1f) { "confidence must be in [0,1], got $confidence" }        require(finalAnswer.isNotBlank()) { "finalAnswer must not be blank" }        require(steps.isNotEmpty()) { "steps must not be empty" }    }}/** * One step in a chain-of-thought reasoning trace. * * @param thought what NOUS is thinking ("Flights cost ₹3-5K, train costs ₹800"). * @param action what NOUS did ("Checking train schedule"). * @param observation what NOUS learned ("Train departs 6 AM, arrives 2 PM"). * @param confidence per-step confidence (0.0–1.0). */data class ReasoningStep(    val thought: String,    val action: String,    val observation: String,    val confidence: Float = 0.8f,) {    init {        require(thought.isNotBlank()) { "thought must not be blank" }        require(confidence in 0f..1f) { "confidence must be in [0,1]" }    }}/** * Result of verifying a reasoning trace (v2 detailed self-correction). * * - [VerificationResult.Verified] — reasoning is sound, answer is correct. * - [VerificationResult.NeedsCorrection] — specific issue found + suggested fix. * - [VerificationResult.Failed] — reasoning is fundamentally flawed. */sealed interface VerificationResult {    data object Verified : VerificationResult    data class NeedsCorrection(        val issue: String,        val suggestedFix: String,    ) : VerificationResult    data class Failed(val reason: String) : VerificationResult}// ═══════════════════════════════════════════════════════════════════════════// 2. PLANNING MODELS// ═══════════════════════════════════════════════════════════════════════════/** * A complete task plan — the output of [com.roshan.persona.cognitive.engine.TaskPlanner]. * * @param rootGoal the original user goal ("Plan a 3-day Goa trip under ₹15,000"). * @param subTasks the decomposed sub-tasks. * @param dependencies maps sub-task ID → list of sub-task IDs it depends on. * @param parallelGroups groups of sub-task IDs that can run in parallel. * @param estimatedResources time + cost + permissions estimate. * @param removedSubTasks sub-tasks removed due to unavailable tools (v2 tool-aware). */data class TaskPlan(    val rootGoal: String,    val subTasks: List<SubTask>,    val dependencies: Map<String, List<String>> = emptyMap(),    val parallelGroups: List<List<String>> = emptyList(),    val estimatedResources: ResourceEstimate = ResourceEstimate(),    val removedSubTasks: List<SubTask> = emptyList(),) {    init {        require(rootGoal.isNotBlank()) { "rootGoal must not be blank" }        require(subTasks.isNotEmpty()) { "subTasks must not be empty" }    }    /** Get a sub-task by ID. */    fun getSubTask(id: String): SubTask? = subTasks.firstOrNull { it.id == id }    /** All sub-task IDs. */    val subTaskIds: List<String> get() = subTasks.map { it.id }}/** * One sub-task in a task plan. * * @param id unique ID (e.g., "research_flights"). * @param description what to do ("Research flights from BLR to GOI"). * @param type sub-task type. * @param estimatedTimeMs estimated execution time. * @param requiredTools tool IDs needed (e.g., ["search_web", "recall_memory"]). * @param canParallelize true if this can run alongside other sub-tasks. */data class SubTask(    val id: String,    val description: String,    val type: SubTaskType,    val estimatedTimeMs: Long = 5_000L,    val requiredTools: List<String> = emptyList(),    val canParallelize: Boolean = true,) {    init {        require(id.isNotBlank()) { "SubTask id must not be blank" }        require(description.isNotBlank()) { "description must not be blank" }        require(estimatedTimeMs >= 0) { "estimatedTimeMs must be non-negative" }    }}/** Types of sub-tasks. */enum class SubTaskType(val displayLabel: String) {    RESEARCH("Research"),    DECISION("Decision"),    ACTION("Action"),    VERIFICATION("Verification"),    SYNTHESIS("Synthesis"),}/** * Resource estimate for a task plan. * * @param estimatedTimeMs total estimated time. * @param estimatedCostUsd estimated cloud LLM cost ($). * @param requiredPermissions permissions needed (e.g., ["INTERNET", "READ_CALENDAR"]). * @param llmCallsEstimated estimated number of LLM calls. */data class ResourceEstimate(    val estimatedTimeMs: Long = 10_000L,    val estimatedCostUsd: Float = 0.01f,    val requiredPermissions: List<String> = emptyList(),    val llmCallsEstimated: Int = 3,) {    init {        require(estimatedTimeMs >= 0) { "estimatedTimeMs must be non-negative" }        require(estimatedCostUsd >= 0f) { "estimatedCostUsd must be non-negative" }        require(llmCallsEstimated >= 0) { "llmCallsEstimated must be non-negative" }    }}// ═══════════════════════════════════════════════════════════════════════════// 3. CLARIFICATION MODELS// ═══════════════════════════════════════════════════════════════════════════/** * A clarifying question NOUS asks the user before planning (v2 P0). * * @param question the question text ("Where would you like to go?"). * @param options optional multiple-choice answers (null = free-text). * @param reasoning why NOUS is asking ("I need to know this because..."). */data class ClarificationQuestion(    val question: String,    val options: List<String>? = null,    val reasoning: String,) {    init {        require(question.isNotBlank()) { "question must not be blank" }        require(reasoning.isNotBlank()) { "reasoning must not be blank" }    }}// ═══════════════════════════════════════════════════════════════════════════// 4. DECISION MODELS// ═══════════════════════════════════════════════════════════════════════════/** * Result of a multi-criteria decision. * * @param options all evaluated options. * @param recommendation the best option. * @param rationale why ("I recommend Android because..."). * @param criteria the decision criteria. * @param userPreferencesApplied preferences from Memory that influenced the decision. * @param confidence 0.0–1.0. */data class DecisionResult(    val options: List<DecisionOption>,    val recommendation: DecisionOption,    val rationale: String,    val criteria: List<DecisionCriterion>,    val userPreferencesApplied: List<String> = emptyList(),    val confidence: Float = 0.8f,) {    init {        require(options.isNotEmpty()) { "options must not be empty" }        require(rationale.isNotBlank()) { "rationale must not be blank" }        require(confidence in 0f..1f) { "confidence must be in [0,1]" }        require(recommendation in options) { "recommendation must be in options" }    }}/** * One option in a decision. * * @param name option name ("iPhone 15 Pro"). * @param scores criterion → score (0.0–1.0). * @param overallScore weighted sum. * @param risks what could go wrong. * @param pros positive aspects. * @param cons negative aspects. */data class DecisionOption(    val name: String,    val scores: Map<String, Float>,    val overallScore: Float,    val risks: List<String> = emptyList(),    val pros: List<String> = emptyList(),    val cons: List<String> = emptyList(),) {    init {        require(name.isNotBlank()) { "name must not be blank" }        require(overallScore in 0f..1f) { "overallScore must be in [0,1]" }        require(scores.values.all { it in 0f..1f }) { "all scores must be in [0,1]" }    }}/** * One criterion in a decision. * * @param name criterion name ("price", "camera", "battery"). * @param weight 0.0–1.0 — higher = more important. * @param description what this criterion means. */data class DecisionCriterion(    val name: String,    val weight: Float = 0.5f,    val description: String = "",) {    init {        require(name.isNotBlank()) { "name must not be blank" }        require(weight in 0f..1f) { "weight must be in [0,1]" }    }}// ═══════════════════════════════════════════════════════════════════════════// 5. PROBLEM SOLVING MODELS// ═══════════════════════════════════════════════════════════════════════════/** * Result of problem solving. * * @param solution the proposed solution. * @param approach how NOUS solved it (pattern match, analogy, creative, constraint). * @param recalledMemory past solution recalled from Memory (null if none). * @param constraintsSatisfied constraints that were met. * @param constraintsRelaxed constraints that had to be relaxed (with explanation). * @param confidence 0.0–1.0. */data class ProblemSolution(    val solution: String,    val approach: SolutionApproach,    val recalledMemory: String? = null,    val constraintsSatisfied: List<Constraint> = emptyList(),    val constraintsRelaxed: List<RelaxedConstraint> = emptyList(),    val confidence: Float = 0.8f,) {    init {        require(solution.isNotBlank()) { "solution must not be blank" }        require(confidence in 0f..1f) { "confidence must be in [0,1]" }    }}/** How NOUS solved the problem. */enum class SolutionApproach(val displayLabel: String) {    /** Recalled a similar past solution from Memory. */    PATTERN_MATCH("Pattern Match"),    /** Applied a solution from a structurally similar domain. */    ANALOGY("Analogical Reasoning"),    /** Combined disparate ideas to create a novel solution. */    CREATIVE("Creative Synthesis"),    /** Worked within explicit constraints. */    CONSTRAINT_SATISFACTION("Constraint Satisfaction"),}/** * A constraint on a problem (explicit or fuzzy). * * @param type constraint type. * @param value the constraint value ("15000", "3 days", "budget-friendly"). * @param isFuzzy true for fuzzy constraints ("budget-friendly") vs explicit ("₹15,000"). * @param description human-readable ("under ₹15,000"). */data class Constraint(    val type: ConstraintType,    val value: String,    val isFuzzy: Boolean = false,    val description: String = "",) {    init {        require(value.isNotBlank()) { "value must not be blank" }    }}/** Types of constraints. */enum class ConstraintType(val displayLabel: String) {    BUDGET("Budget"),    TIME("Time"),    DURATION("Duration"),    LOCATION("Location"),    PREFERENCE("Preference"),    PERMISSION("Permission"),    CUSTOM("Custom"),}/** * A constraint that had to be relaxed (per Q4: ask user or auto-relax with explanation). * * @param originalConstraint the original constraint. * @param relaxedValue the new value after relaxation. * @param reason why it was relaxed ("Budget too tight for flight; increased by ₹500"). */data class RelaxedConstraint(    val originalConstraint: Constraint,    val relaxedValue: String,    val reason: String,) {    init {        require(relaxedValue.isNotBlank()) { "relaxedValue must not be blank" }        require(reason.isNotBlank()) { "reason must not be blank" }    }}// ═══════════════════════════════════════════════════════════════════════════// 6. REPLANNING MODELS// ═══════════════════════════════════════════════════════════════════════════/** * Result of a replanning attempt (v2 P0 — ReplanningEngine). * * - [ReplanResult.Replanned] — new plan generated, execution continues. * - [ReplanResult.Skipped] — failed sub-task skipped, execution continues. * - [ReplanResult.AskUser] — can't auto-resolve, asking user. * - [ReplanResult.Failed] — re-planning failed, workflow stops. */sealed interface ReplanResult {    data class Replanned(val newPlan: TaskPlan, val message: String) : ReplanResult    data class Skipped(val message: String) : ReplanResult    data class AskUser(val question: String) : ReplanResult    data class Failed(val reason: String) : ReplanResult}/** * Result of executing a task plan via Brain's Agentic Layer. * * @param status overall execution status. * @param completedSubTasks sub-tasks that succeeded. * @param failedSubTasks sub-tasks that failed. * @param replansTriggered how many times re-planning was triggered. * @param reasoningTrace the reasoning trace for this execution. */data class PlanExecutionResult(    val status: PlanStatus,    val completedSubTasks: List<SubTask>,    val failedSubTasks: List<SubTask>,    val replansTriggered: Int = 0,    val reasoningTrace: ReasoningTrace? = null,) {    init {        require(replansTriggered >= 0) { "replansTriggered must be non-negative" }    }}/** Overall plan execution status. */enum class PlanStatus(val displayLabel: String) {    COMPLETED("Completed"),    PARTIAL("Partially Completed"),    FAILED("Failed"),    TIMEOUT("Timed Out"),}/** Status of a single sub-task during execution. */enum class ExecutionStatus(val displayLabel: String) {    PENDING("Pending"),    RUNNING("Running"),    SUCCEEDED("Succeeded"),    FAILED("Failed"),    SKIPPED("Skipped"),}// ═══════════════════════════════════════════════════════════════════════════// 7. STORAGE MODELS// ═══════════════════════════════════════════════════════════════════════════/** * A stored reasoning trace (v2 — persistent, 30-day TTL). * * @param traceId unique ID. * @param timestamp when the trace was created. * @param userQuery the original user query. * @param trace the reasoning trace. * @param userFeedback user's reaction (null = no feedback yet). * @param correctionNote user's correction note (if CORRECTED). */data class StoredReasoningTrace(    val traceId: String,    val timestamp: Long,    val userQuery: String,    val trace: ReasoningTrace,    val userFeedback: UserFeedback? = null,    val correctionNote: String? = null,) {    init {        require(traceId.isNotBlank()) { "traceId must not be blank" }        require(userQuery.isNotBlank()) { "userQuery must not be blank" }    }}/** User's feedback on a recommendation (for PreferenceLearner in v3). */enum class UserFeedback(val displayLabel: String) {    ACCEPTED("Accepted"),    REJECTED("Rejected"),    CORRECTED("Corrected"),}// ═══════════════════════════════════════════════════════════════════════════// 8. UNCERTAINTY MODELS// ═══════════════════════════════════════════════════════════════════════════/** * Action to take when NOUS is uncertain (v2 — UncertaintyAwareness). * * - [UncertaintyAction.Answer] — confidence is high enough; answer normally. * - [UncertaintyAction.AskFollowUp] — medium confidence; ask a follow-up question. * - [UncertaintyAction.SearchWeb] — low confidence; search for information. * - [UncertaintyAction.AdmitUnknown] — very low confidence; admit "I don't know." */sealed interface UncertaintyAction {    data object Answer : UncertaintyAction    data class AskFollowUp(val question: String) : UncertaintyAction    data class SearchWeb(val query: String) : UncertaintyAction    data class AdmitUnknown(val message: String) : UncertaintyAction}
